#!/bin/bash
# The exact v5 TRAIN command, generated by --print-launch (not written from memory),
# now that BOTH caches are renamed + registered.
set -u
export PYTHONPATH=/workspace/v5eval/stack
export OMP_NUM_THREADS=6
cd /workspace/v5eval/stack
TR=/workspace/data/physicalai-train-e438721ae894-w120-256x640cyl
VA=/workspace/data/physicalai-val-0c5f7dac3b11-w120-256x640cyl

run () {
  echo "######## $1"
  shift
  python3 -u scripts/train_flagship_v4.py "$@" --print-launch 2>&1 | tail -30
  echo "EXIT: ${PIPESTATUS[0]}"
  echo
}

COMMON=(--v2-train-cache "$TR" --v2-val-cache "$VA" --v2-lru 64 --require-parity
        --frame-h 256 --frame-w 640 --frame-hfov 120 --projection cylindrical
        --from-scratch
        --anchors-dense /workspace/experiments/anchors/anchors_dense_1to20.pt
        --out /workspace/experiments/flagship-v5-w120-rigclean-30k
        --steps 30000 --batch 16 --accum 4 --lr-head 1e-4 --lr-trunk 1e-4
        --warmup 2000 --workers 8 --eval-every 500 --save-every 1000 --rollout-k 4
        --heldout-gate --heldout-every 2000 --heldout-episodes 8 --heldout-patience 2
        --device cuda)

run "A. WITH --v2-subframe 176x624 (expected PREFLIGHT: OK)" "${COMMON[@]}" --v2-subframe 176x624
run "B. WITHOUT the flag (expected PREFLIGHT: BLOCKED, exit 2)" "${COMMON[@]}"
